import re, pathlib
B=pathlib.Path('/home/claude/work/v3')
src=(B/'concept.md').read_text(encoding='utf8')
S={p.stem:p.read_text(encoding='utf8').strip() for p in (B/'snippets').glob('*.md')}
def blk(name):
    t=(B/'blocks'/f'{name}.md').read_text(encoding='utf8')
    for k,v in S.items(): t=t.replace('{{'+k+'}}',v)
    assert '{{' not in t, name
    return t
s=src
def rep(a,b,count=1):
    global s
    n=s.count(a)
    assert n==count, (n,a[:90])
    s=s.replace(a,b)
def rep_line_start(prefix,new):
    global s
    lines=s.split('\n'); idx=[i for i,l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx)==1,(prefix,len(idx))
    lines[idx[0]]=new; s='\n'.join(lines)
def between(start,end,new):
    global s
    i=s.index(start); j=s.index(end,i)
    s=s[:i]+new+s[j:]
def insert_after_line(prefix,text):
    global s
    lines=s.split('\n'); idx=[i for i,l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx)==1,(prefix,len(idx))
    lines.insert(idx[0]+1,text); s='\n'.join(lines)
def insert_before(anchor,text):
    global s
    assert s.count(anchor)==1, anchor
    s=s.replace(anchor,text+anchor)

